CREATE SCHEMA IF NOT EXISTS inventory;

CREATE TABLE IF NOT EXISTS inventory.route_rules (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    sequence INTEGER NOT NULL DEFAULT 20,
    action rule_action NOT NULL DEFAULT 'pull',
    auto rule_auto NOT NULL DEFAULT 'manual',
    procure_method procure_method NOT NULL DEFAULT 'make_to_stock',
    delay INTEGER NOT NULL DEFAULT 0,
    location_src_id UUID,
    location_dest_id UUID NOT NULL,
    picking_type_id UUID NOT NULL,
    route_id UUID NOT NULL,
    warehouse_id UUID,
    company_id UUID,
    propagate_cancel BOOLEAN NOT NULL DEFAULT FALSE,
    metadata JSONB NOT NULL DEFAULT '{"created_at":null,"updated_at":null,"deleted_at":null,"created_by":null,"updated_by":null,"deleted_by":null}'::jsonb,
    PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS idx_route_rules_route_id ON inventory.route_rules (route_id);

CREATE INDEX IF NOT EXISTS idx_route_rules_action ON inventory.route_rules (action);

